import numpy as np
from PIL import Image
from scipy import ndimage
import json

BASE='/home/mato/.cache/real-chart-bench/codex-local/work/pixcal/qwen3.8-27b/part7'

def load(name):
    return np.asarray(Image.open(f'{BASE}/images/{name}.png').convert('RGB')).astype(np.int32)

def color_mask(a, color, tol=40):
    return (np.abs(a - np.array(color)).max(axis=2) <= tol)

def find_markers(M, win=11, thr=18, refine_r=7, min_area=4):
    \"\"\"Find marker centers in boolean mask M using local density peaks.\"\"\"
    dens = ndimage.uniform_filter(M.astype(np.float32), size=win) * win * win
    mx = ndimage.maximum_filter(dens, size=win)
    peak = (dens >= mx) & (dens > thr)
    ys, xs = np.nonzero(peak)
    # cluster peaks closer than win//2 (plateau merging already handled; dedupe anyway)
    pts = list(zip(xs, ys))
    pts.sort()
    merged = []
    H, W = M.shape
    for x, y in pts:
        placed = False
        for g in merged:
            if abs(g['x']-x) < win//2 and abs(g['y']-y) < win//2:
                g['n'] += 1; placed = True; break
        if not placed:
            merged.append({'x':x, 'y':y, 'n':1})
    out = []
    yy, xx = np.nonzero(M)
    for g in merged:
        d2 = (xx - g['x'])**2 + (yy - g['y'])**2
        sel = d2 <= refine_r**2
        if sel.sum() < min_area:
            continue
        cx = xx[sel].mean(); cy = yy[sel].mean()
        out.append((cx, cy, int(sel.sum())))
    out.sort(key=lambda t: t[0])
    return out

def exclude_rects(M, rects):
    M = M.copy()
    for (x0,y0,x1,y1) in rects:
        M[int(y0):int(y1)+1, int(x0):int(x1)+1] = False
    return M

def px2val(px, ticks, scale):
    (p0,v0),(p1,v1) = ticks
    if scale=='linear':
        return v0 + (px-p0)*(v1-v0)/(p1-p0)
    else:
        return 10**(np.log10(v0) + (px-p0)*(np.log10(v1)-np.log10(v0))/(p1-p0))

def show(name, series_list, xticks, yticks, xscale, yscale):
    a = load(name)
    result = {}
    for label, mask_fn, opts in series_list:
        M = mask_fn(a)
        for k,v in opts.items():
            if k=='rects': M = exclude_rects(M, v)
        mk = find_markers(M, **{k:v for k,v in opts.items() if k"'!='"'rects'})
        xs = [round(px2val(px, xticks, xscale),4) for px,py,ar in mk]
        ys = [round(px2val(py, yticks, yscale),4) for px,py,ar in mk]
        result[label] = (xs, ys)
        print(f'{label}: {len(mk)} pts  x[{min(xs):.2f},{max(xs):.2f}] y[{min(ys):.3f},{max(ys):.3f}]')
        print('   x:', xs)
        print('   y:', ys)
    return result
